package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSiDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujood)", "(අල්ලාහ්) මහිමයට පත්, අතිශුද්ධ, දේවදූතයන්ගේ සහ ආත්මයේ (ජිබ්රිල්) ස්වාමියාය.", "රුකු සහ සුජූද්හි.", "ﷺ නබිතුමා මෙය රුකූ සහ සුජූද් වලින් පාරායනය කළේය."),
        "dua_sujood_dhanbi_kullah" to DuaText("සුජූද් හි: මගේ සියලු පව් සමාව දෙන්න", "අල්ලාහ්, මගේ සියලු පාපයන් මට සමාව දෙන්න - කුඩා හා විශාල, පළමු සහ අවසාන, විවෘත සහ සැඟවුණු.", "සුජූද් හි.", "සුජූද් යනු දුආස් වලට පිළිතුරු දෙන ස්ථානයකි."),
        "dua_sujood_ridaka" to DuaText("ඔබේ සතුට සරණයි", "අල්ලාහ්, මම ඔබේ කෝපයෙන් ඔබේ සතුටෙන්, ඔබේ දඬුවමෙන් ඔබේ සමාවෙන්, මම ඔබගෙන් ආරක්ෂාව පතමි. මට ඔබට සම්පූර්ණයෙන් ප්‍රශංසා කළ නොහැක; ඔබ ඔබම ප්‍රශංසා කළ ආකාරයටමයි.", "සුජූද්හි — අයිෂා (RA) ට නබි ﷺ මෙසේ කියනු ඇසිණි.", "ﷺ නබිතුමාගේ සුජූද් දුආවක්."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyat)", "සියලුම වාචික, භෞතික සහ මූල්‍ය නමස්කාරය අල්ලාහ් සඳහා වේ. නබි තුමනි, ඔබට සාමය සහ අල්ලාහ්ගේ දයාව සහ ඔහුගේ ආශිර්වාදය ලැබේවා. අපට සහ අල්ලාහ්ගේ දැහැමි සේවකයන්ට සාමය ලැබේවා. අල්ලාහ් හැර නැමදුම් ලැබීමට සුදුසු වෙනත් කිසිවෙක් නැති බව මම සාක්ෂි දරයි, මුහම්මද් ﷺ ඔහුගේ සේවකයා සහ දූතයා බව මම සාක්ෂි දෙමි.", "සෑම වාඩිවීමකදීම - අබ්දුල්ලා ඉබ්න් මස්උද් (RA) (හනාෆි පිළිවෙත) විසින් විස්තර කරන ලදී.", "ﷺ නබිතුමා එය කුර්ආනයේ සූරතයක් මෙන් ඉගැන්වීය."),
        "dua_sajdah_tilawah" to DuaText("පාරායනය කිරීමේ සජ්දා", "මාගේ මුහුණ එය මවා ඔහුගේ බලයෙන් සහ බලයෙන් එහි ඇසීම සහ පෙනීම ඇති කළ තැනැත්තාට වැඳ වැටී ඇත.", "පාරායනය කිරීමේ සුජූද්හි.", "ﷺ නබිතුමා රාත්‍රියේ පාරායනය කිරීමේ සුජූද්හිදී මෙය ප්‍රකාශ කළේය."),
        "dua_after_witr" to DuaText("Witr පසු", "අතිශුද්ධ වූ රජුට මහිමය වේවා.", "විත්ර් සලාම් වලින් පසු තුන් වරක්, තුන්වන වතාවට හඬ නඟා.", "ﷺ නබිතුමා විත්ර්ගෙන් පසු මෙය පැවසීය."),
        "dua_tahajjud_nur" to DuaText("තහජ්ජුද් විවෘත කිරීමේ ආයාචනය", "අල්ලාහ්, ඔබට ප්‍රශංසාව හිමි වේ. ඔබ අහසේ, පොළොවේ සහ ඒවා තුළ ඇති සියල්ලේ පෝෂකය. ප්‍රශංසාව ඔබට අයිතියි; ඔබ අහසේ, පොළොවේ සහ ඒවා තුළ ඇති සියල්ලේ ආලෝකය වේ. ප්‍රශංසාව ඔබට අයිතියි; ඔබ සත්‍යය, ඔබේ පොරොන්දුව සත්‍ය, ඔබ සමඟ හමුවීම සත්‍ය, ඔබේ වචනය සත්‍ය, පාරාදීසය සත්‍ය, නිරය සත්‍ය, නබිවරුන් සත්‍ය, මුහම්මද් ﷺ සත්‍ය සහ පැය සත්‍ය වේ.", "රාත්රී සලාතය (තහජ්ජුද්) ආරම්භ කරන විට (දුවාහි ආරම්භක කොටස).", "ﷺ නබිතුමා මෙය තහජ්ජුද් සඳහා නැගීමේදී පාරායනය කළේය (සම්පූර්ණ දූවා අල්-බුහාරි හි ඇත)."),
        "dua_rabba_jibrail" to DuaText("මතභේදාත්මක කරුණු වලදී මට මඟ පෙන්වන්න", "අල්ලාහ්, ජිබ්‍රිල්, මිකායිල් සහ ඉස්රාෆිල්ගේ ස්වාමියා, අහස් හා පොළොවේ මැවුම්කරු, අදෘශ්‍යමාන හා දෘශ්‍ය දේ දන්නා අය! ඔබ ඔබේ සේවකයන් අතර ඔවුන් වෙනස් වූ දේ ගැන විනිශ්චය කරන්නෙහිය. වෙනස් වූ දෙයෙහි සත්‍යය වෙත ඔබගේ අවසරයෙන් මට මග පෙන්වන්න. නියත වශයෙන්ම ඔබ කැමති අයව ඍජු මාර්ගයට යොමු කරන්න.", "තහජ්ජුද් ආරම්භයේදී - එකඟ නොවීම් මධ්‍යයේ සත්‍යයට මග පෙන්වීම සඳහා.", "ﷺ නබිතුමා සිය රාත්‍රී යාඥාව ආරම්භ කළේ මෙම දුආ සමඟිනි."),
        "dua_going_to_mosque_nur" to DuaText("පල්ලියට යාම (ආලෝකයේ ඩුවා)", "අල්ලාහ්, මගේ හදවතේ ආලෝකය, මගේ ඇස්වල ආලෝකය, මගේ කන්වල ආලෝකය, මගේ දකුණේ ආලෝකය, මගේ වම් පසින් ආලෝකය, මට ඉහළින් ආලෝකය, මට පහළින් ආලෝකය, මා ඉදිරියෙහි ආලෝකය, මා පිටුපස ආලෝකය, සහ මට ආලෝකය ලබා දෙන්න.", "ෆජ්ර් සඳහා පල්ලියට යන අතරතුර.", "නබි ﷺ සලාතය සඳහා පිටතට යන විට මෙය පාරායනය කළේය."),
        "dua_waswasa_salah" to DuaText("Waswasa සලාහ් අතරතුර (Khinzab)", "ශාප ලත් ෂෙයිතාන්ගෙන් මම අල්ලාහ්ගෙන් රැකවරණය පතමි.", "යාච්ඤාව අතරතුර සාතන්ගේ මුමුණන විට, රැකවරණය පතන්න සහ තෙවරක් වමට සැහැල්ලුවෙන් කෙළ ගසන්න.", "Uthman ibn Abil-'As (RA) මෙය කළ අතර රහසින් පිටව ගියේය."),
        "dua_alimal_ghayb" to DuaText("නොපෙනෙන දේ දන්නා", "අහෝ අල්ලාහ්, අදෘශ්‍යමාන හා දෘශ්‍යමාන දේ දන්නා, අහස් හා පොළොවේ මැවුම්කරු, සියලු දේවල ස්වාමියා සහ පරමාධිපතිය! ඔබ හැර වෙනත් දෙවියෙකු නොමැති බවට මම සාක්ෂි දෙමි. මගේම නපුරෙන්ද, ෂෙයිතාන්ගේ නපුරෙන් සහ ඔහුගේ ෂිර්ක්ගෙන්ද මම ඔබගෙන් රැකවරණය පතමි.", "උදේ, සවස සහ නින්දට පෙර - නබි ﷺ එය අබු බකර් (RA) ට ඉගැන්වීය.", "තමාගේ සහ ෂෙයිතාන්ගේ නපුරෙන් ආරක්ෂා වීම."),
        "dua_fitratil_islam" to DuaText("ඉස්ලාමයේ ෆිත්රා මත", "අපි ඉස්ලාමයේ ෆිත්‍රා මත, අවංකභාවයේ වචනය මත, අපගේ නබි මුහම්මද් ﷺ ගේ ආගම මත සහ බහුදේවවාදීන්ගේ නොවූ අවංක සහ මුස්ලිම්වරයෙකු වූ අපගේ පියා ඊබ්‍රාහිම් (AS) ගේ මාර්ගයට ඇතුළු වී සිටිමු.", "උදෑසන.", "සෑම උදෑසනකම කෙනෙකුගේ ඇදහිල්ල අලුත් කිරීම."),
        "dua_amsayna_fitrah" to DuaText("ඉස්ලාමයේ ෆිත්රා මත සවස", "අපි ඉස්ලාමයේ ෆිත්‍රා මත, අවංකභාවයේ වචනය මත, අපගේ නබි මුහම්මද් ﷺ ගේ ආගම මත සහ බහුදේවවාදීන්ගේ නොවූ අවංක හා මුස්ලිම් වූ අපගේ පියා වූ ඊබ්‍රාහිම් (AS) ගේ මාර්ගයට ඇතුළු වී සිටිමු.", "හවස.", "සෑම සවසකම කෙනෙකුගේ ඇදහිල්ල අලුත් කිරීම."),
        "dua_tahleel_10_fajr" to DuaText("ෆජ්ර් සහ මග්රිබ්ට පසු තහ්ලීල් දහය", "හවුල්කරුවෙකු නොමැතිව තනිව අල්ලාහ් හැර නැමදුම් ලැබීමට සුදුසු වෙනත් කිසිවෙක් නැත. ආධිපත්‍යය ඔහු සතුය, ප්‍රශංසාව ඔහුගේය; ඔහු ජීවය ලබා දෙයි, මරණයට පත් කරයි, ඔහු සියල්ල කෙරෙහි බලය ඇත.", "ෆජ්ර් (සහ මග්රිබ්) පසු දස වරක්, ඔබේ වාඩි වී හෝ කතා කිරීමෙන් පෙර.", "යහපත් ක්‍රියා දසයක්, පව් දහයක් මකා දැමූහ, තරාතිරම දහයක් ඔසවා, දවස පුරා ෂෙයිතාන්ගෙන් ආරක්ෂාව."),
        "dua_la_hawla_kanz" to DuaText("ජන්නාගේ නිධානයක්", "අල්ලාහ් සමඟ මිස බලයක් හා බලයක් නැත.", "බොහෝ විට, සෑම විටම.", "එය පාරාදීසයේ නිධානයන්ගෙන් එකකි."),
        "dua_four_beloved_words" to DuaText("වඩාත්ම ආදරණීය වචන හතර", "අල්ලාහ්ට මහිමය වේවා, සියලු ප්‍රශංසාව අල්ලාහ්ටය, අල්ලාහ් හැර නැමදුම් ලැබීමට සුදුසු වෙනත් කිසිවෙක් නැත, අල්ලාහ් ශ්‍රේෂ්ඨය.", "අල්ලාහ්ට වඩාත්ම ආදරණීය වචන.", "ඔවුන් ﷺ නබිතුමාට හිරු උදාවන සෑම දෙයකටම වඩා ආදරණීයයි."),
        "dua_two_light_words" to DuaText("වචන දෙකක් දිව මත ආලෝකය", "මහිමය අල්ලාහ්ට වේවා සියලු ප්‍රශංසාව ඔහුටයි. අතිවිශිෂ්ට අල්ලාහ්ට මහිමය වේවා.", "දිව මත ආලෝකය, පරිමාණය මත බර.", "මහා කාරුණික දෙවියන්ට ප්‍රියයි, දිවට ආලෝකය සහ තරාදියට බරයි. (අල්-බුහාරිගේ අවසාන හදීසය)"),
        "dua_ya_dhal_jalal" to DuaText("යා Dal-Jalali wal-Ikram", "අහෝ මහිමය හා ගෞරවය හිමිකරුවා!", "එය dua හි අල්ලාගෙන සිටින්න - නබිතුමාගේ ﷺ උපදෙස්.", "ﷺ නබිතුමා පැවසුවේ: 'යා Dal-Jalali wal-Ikram' අල්ලාගෙන සිටින්න."),
        "dua_sleep_wadatu_janbi" to DuaText("ඔබේ නාමයෙන් මම වැතිර සිටිමි", "ඔබගේ නාමයෙන්, මාගේ ස්වාමීනි, මම මාගේ පැත්ත තබා ඔබගේ නාමයෙන් මම නැඟිටිමි. ඔබ මාගේ ආත්මය ගන්නේ නම්, එයට අනුකම්පා කරන්න, ඔබ එය නිදහස් කරන්නේ නම්, ඔබ ඔබේ ධර්මිෂ්ඨ සේවකයන් ආරක්ෂා කරන ආකාරයටම එය ආරක්ෂා කරන්න.", "ඇඳේ දූවිලි පිසදමා නිදාගත් පසු.", "නින්දට පෙර තම ආත්මය අල්ලාහ්ට භාර දීම."),
        "dua_sleep_khalaqta_nafsi" to DuaText("ඔබ මගේ ආත්මය නිර්මාණය කළා", "අල්ලාහ්, ඔබ මාගේ ආත්මය මැවූ අතර ඔබ එය ගනු ඇත. එහි මරණයත් ජීවිතයත් අයිති ඔබටයි. ඔබ එය ජීවත් කරවන්නේ නම්, එය ආරක්ෂා කරන්න, ඔබ එය මරණයට පත් කරන්නේ නම්, එයට සමාව දෙන්න. අල්ලාහ්, මම ඔබෙන් යහපැවැත්ම ඉල්ලා සිටිමි.", "නින්දට පෙර - ඉබ්නු උමර් (RA) විසින් විස්තර කරන ලදී.", "ﷺ නබිතුමා නින්දට යන විට මෙය පැවසීමට උපදෙස් දුන්නේය."),
        "dua_sleep_atamana" to DuaText("නින්දට පෙර කෘතඥතාව", "සියලු ප්‍රශංසාව අපට පෝෂණය කළ, බීම දුන්, අපට සෑහීමට දුන්, අපට රැකවරණය දුන් අල්ලාහ්ටය. සෑහීමට පත් වීමට හෝ ඔවුන්ට සෙවණ දෙන්නට කිසිවෙක් නැති කීයෙන් කීදෙනාද.", "ඇඳට යන විට.", "ﷺ නබිතුමා නින්දට යන විට මෙය පැවසුවා."),
        "dua_sleep_rabbas_samawat" to DuaText("ස්වර්ගයේ ස්වාමියා - අපගේ ණය ගෙවන්න", "අහස්, පොළොව සහ බලවත් සිංහාසනයේ ස්වාමියා වන අල්ලාහ්, අපගේ ස්වාමියා සහ සියල්ලේ ස්වාමියා, බීජ සහ ඉඳි ගල බෙදන්නා, ටෝරා, ඉන්ජිල් සහ ෆුර්කාන් හෙළි කරන්නා! ඔබ මාරයා අල්ලාගෙන සිටින සෑම දෙයකම නපුරෙන් මම ඔබගෙන් රැකවරණය පතමි. අල්ලාහ්, ඔබ පළමුවැන්නා, ඔබ ඉදිරියෙහි කිසිවක් නැත; ඔබ අන්තිමයාය, ඔබෙන් පසු කිසිවක් නැත; ඔබ ප්‍රකාශනයයි, ඔබට ඉහළින් කිසිවක් නැත; ඔබ සැඟවී ඇත, ඔබගෙන් සැඟවුණු කිසිවක් නැත. අප වෙනුවෙන් අපගේ ණය පියවා දිළිඳුකමින් අපව නිදහස් කරන්න.", "නින්දට පෙර, දකුණු පැත්තේ වැතිර සිටීම - ෆාතිමා (RA) ට උගන්වා ඇත.", "ණය සහ දුෂ්කරතා වලින් සහන සඳහා වූ දුආවක්."),
        "dua_sleep_fear" to DuaText("නින්දේදී බිය හෝ නොසන්සුන්තාවය", "අල්ලාහ්ගේ කෝපයෙන් සහ ඔහුගේ දඬුවමෙන්, ඔහුගේ සේවකයන්ගේ නපුරෙන්, යක්ෂයින්ගේ මුමුණමින් සහ ඔවුන් මා වෙත පැමිණීමෙන් මම අල්ලාහ්ගේ පරිපූර්ණ වචනවලින් රැකවරණය පතමි.", "නින්දේදී බියක් හෝ නොසන්සුන්තාවයක් දැනෙන විට.", "එසේ කිරීමෙන් ඒ දෙය ඔහුට හානියක් නොවේ."),
        "dua_waking_afani" to DuaText("පිබිදීම: ඔහු මගේ ආත්මය යථා තත්වයට පත් කළේය", "සියලු ප්‍රශංසාව මගේ ශරීරයට යහපැවැත්ම ලබා දුන්, මගේ ආත්මය මා වෙත ආපසු ලබා දුන් සහ ඔහුව සිහිපත් කිරීමට මට ඉඩ දුන් අල්ලාහ්ට ය.", "අවදි වන විට.", "නව උදෑසනක් සඳහා කෘතඥතාව."),
        "dua_allahu_rabbi" to DuaText("අල්ලාහ්, අල්ලාහ් මාගේ ස්වාමියාය", "අල්ලාහ්, අල්ලාහ් මාගේ ස්වාමියා ය; මම ඔහු සමඟ කිසිවක් ඇසුරු නොකරමි.", "ශෝකයෙන් හෝ විපතේදී - නබි ﷺ එය අස්මා බින්ට් උමයිස් (RA) ට ඉගැන්වීය.", "විපත්ති කාලවලදී තව්හීද් අල්ලාගෙන සිටීම."),
        "dua_rahmataka_arju" to DuaText("ඔබගේ දයාව මම බලාපොරොත්තු වෙනවා", "අල්ලාහ්, මා බලාපොරොත්තු වන්නේ ඔබගේ දයාවයි, එබැවින් ඇසිපිය හෙළන මොහොතකටවත් මා මා වෙත හැර නොයවා, මාගේ සියලු කටයුතු නිවැරදි කරනු මැනව. ඔබ හැර වෙන දෙවි කෙනෙක් නැත.", "විපතට පත් තැනැත්තාගේ දූව (Daawat al-makrub).", "ﷺ නබිතුමා එය හැඳින්වූයේ විපතට පත් වූ තැනැත්තාගේ දුආ ලෙසයි."),
        "dua_against_enemy_ahzab" to DuaText("සතුරාගේ හමුදාවන්ට එරෙහිව", "අල්ලාහ්, ග්‍රන්ථය එළිදරව් කරන්නා, ගණන් කිරීමේදී ඉක්මන්! සංගම් පරාජය කරන්න. අල්ලාහ්, ඔවුන් පරාජය කර ඔවුන් සොලවන්න.", "සතුරාට එරෙහිව - කොන්ෆෙඩරේට්ස් සටනේ dua.", "නබිතුමාගේ ﷺ දුවා සතුරාට එරෙහිව."),
        "dua_anta_adudi" to DuaText("ඔබ මගේ සහායයි", "අල්ලාහ්, ඔබ මාගේ සහාය සහ මගේ සහායකයා වේ. ඔබ විසින් මම සැලසුම් කරමි, ඔබ විසින් මම ඉදිරියට යමි සහ ඔබ විසින් මම සටන් කරමි.", "තරඟයකට හෝ ප්‍රධාන අභියෝගයකට පෙර.", "ﷺ නබිතුමා සටනේදී මෙය කීවේය."),
        "dua_ikfinihim" to DuaText("ඔවුන්ට එරෙහිව මා ප්‍රමාණවත්", "අල්ලාහ්, ඔබ කැමති කෙසේ වෙතත් ඔවුන්ට එරෙහිව මට ප්‍රමාණවත්.", "පීඩකයන්ගේ නපුරට එරෙහිව - වළේ මිනිසුන්ගේ කතාවේ පිරිමි ළමයාගේ දූව.", "අල්ලාහ් කොල්ලකරුවන්ගෙන් පිරිමි ළමයා බේරා ගත්තේය."),
        "dua_qadarullah" to DuaText("නරක දෙයක් සිදු වූ විට", "එය අල්ලාහ්ගේ නියෝගය වන අතර, ඔහු කැමති දේ කළේය.", "අමිහිරි දෙයක් සිදු වූ විට, ‘එසේ නම් පමණක්’ කියනු වෙනුවට.", "'එසේ නම්' ෂෙයිතාන්ට දොර විවර කරයි."),
        "dua_ala_kulli_hal" to DuaText("සෑම අවස්ථාවකදීම ප්රශංසා කරන්න", "සෑම අවස්ථාවකදීම සියලු ප්‍රශංසා අල්ලාහ්ට වේ.", "අකමැති දෙයක් සිදු වූ විට.", "ﷺ නබිතුමා මෙය පැවසුවේ තමා අකමැති දෙයකට මුහුණ දීමෙනි."),
        "dua_dogs_barking" to DuaText("රාත්‍රියේ බල්ලන් බුරන හඬ ඇසේ", "ශාප ලත් ෂෙයිතාන්ගෙන් මම අල්ලාහ්ගෙන් රැකවරණය පතමි.", "රාත්‍රියේදී බල්ලන් බුරන හඬ හෝ බූරු හඬ ඇසීමෙන්.", "ඔබ නොදකින දේ ඔවුන් දකියි."),
        "dua_leaving_home_adilla" to DuaText("නොමග යාමෙන් රැකවරණය", "අල්ලාහ්, මා නොමග නොයන ලෙසට හෝ නොමඟ නොයන ලෙසට, මා ලිස්සා යාමට හෝ ලිස්සා යාමට ඉඩ නොතබන ලෙසට, මා වැරදි කිරීමට හෝ අසාධාරණයට ලක් නොවන පරිදි, මා මෝඩ ලෙස හැසිරීමට හෝ මෝඩ ලෙස සැලකීමට ඉඩ නොතබන ලෙස මම ඔබගෙන් සරණ පතමි.", "නිවසින් පිටව යන විට - උම්ම් සලාමා (RA) විසින් විස්තර කරන ලදී.", "නබිතුමා ﷺ තම නිවසින් පිටවන සෑම විටම මෙය පාරායනය කළේය."),
        "dua_ascending_descending" to DuaText("උඩ යනවා පහළට එනවා", "අල්ලාහ් ශ්‍රේෂ්ඨය (ඉහළ යන විට). - අල්ලාහ්ට මහිමය (බසින විට).", "ගමනකදී ඉහළට යන විට ‘අල්ලාහු අක්බර්’ සහ පහළට එන විට ‘සුභාන් අල්ලාහ්’ කියන්න.", "සහචරයන්ගේ භාවිතය (RA) ගමන් කරන අතරතුර."),
        "dua_traveller_sahar" to DuaText("උදාවීමට පෙර සංචාරකයාගේ දූව", "සවන්දෙන්නෙකු අල්ලාහ්ට අපගේ ප්‍රශංසාව සහ ඔහුගේ යහපත් අනුග්‍රහයන් අසා ඇත (සහ එය සම්මත කර ඇත). අපගේ ස්වාමීනි, අපව කැටුව ගොස් ඔබගේ අනුග්‍රහය අපට ලබා දෙන්න - (මම මෙය කියමි) ගින්නෙන් අල්ලාහ්ගෙන් ආරක්ෂාව පතා.", "ගමනක, උදාවීමට පෙර.", "ﷺ නබිතුමා ගමන් කරන විට උදාවීමට පෙර මෙය ප්‍රකාශ කළේය."),
        "dua_zawwadakallah" to DuaText("සංචාරකයාට: අල්ලාහ් තක්වා ලබා දෙයි", "ඔබගේ ගමන සඳහා අල්ලාහ් ඔබට තක්වා ලබා දෙයි, ඔබේ පව් වලට සමාව දී ඔබ කොතැනක සිටියත් ඔබට යහපත පහසු කරයි.", "සංචාරකයෙකුට සමුගැනීමේදී.", "ﷺ නබිතුමා ගමනක් යන කෙනෙකුට මෙම දුආ ලබා දුන්නේය."),
        "dua_traveller_to_resident" to DuaText("පිටුපස රැඳී සිටින අය වෙත සංචාරකයා", "මම ඔබව අල්ලාහ්ට භාර කරමි, ඔහු කෙරෙහි විශ්වාසය කිසිදා නැති නොවේ.", "පවුලේ අයගෙන් සමුගන්නා විට සංචාරකයා විසින් පවසන ලදී.", "පවුලේ ආරක්ෂාව අල්ලාහ්ට පැවරීම."),
        "dua_entering_village" to DuaText("නගරයකට හෝ ගමකට ඇතුළු වීම", "අල්ලාහ්, අහස් හතට සහ ඔවුන් සෙවණ ඇති සියල්ලට ස්වාමීනි, මිහිතල හතට සහ ඔවුන් රැගෙන යන සියල්ලට ස්වාමීනි, යක්ෂයන්ගේ සහ ඔවුන් නොමඟ යවන සියල්ලන්ගේ ස්වාමියා, සුළඟට සහ ඔවුන් විසිරී යන සියල්ලට අධිපති! අපි ඔබෙන් මේ නගරයේ යහපත සහ එහි මිනිසුන්ගේ යහපත ඉල්ලා සිටින අතර, එහි නපුරෙන්, එහි මිනිසුන්ගේ නපුරෙන් සහ එහි ඇති දේවල නපුරෙන් අපි ඔබගෙන් රැකවරණය පතන්නෙමු.", "නගරයකට හෝ නගරයකට ඇතුළු වීමට පෙර.", "ﷺ නබිතුමා නගරයකට ඇතුළු වීමට කැමති සෑම විටම මෙය පාරායනය කළේය."),
        "dua_vehicle_stumbles" to DuaText("වාහනය පැකිළෙන විට", "අල්ලාහ්ගේ නාමයෙන්.", "කන්ද හෝ වාහනය ලිස්සන විට හෝ පැකිළෙන විට, 'ෂෙයිතාන් විනාශ වේවා' කියා කියනවා වෙනුවට.", "බිස්මිල්ලා කීම ෂෙයිතාන් මැස්සෙකුගේ ප්‍රමාණයට හැකිලී යයි."),
        "dua_ajz_kasal_haram" to DuaText("දුර්වලකම සහ මහලු වියේ රැකවරණය", "අල්ලාහ්, අසරණ භාවයෙන් හා කම්මැලිකමින්, බියගුලුකමෙන් සහ මහලු වියෙන්, ජීවිතය හා මරණය පිළිබඳ පරීක්ෂාවන්ගෙන් සහ සොහොන් දඬුවමෙන් මම ඔබගෙන් රැකවරණය පතමි.", "සරණ යන විස්තීර්ණ දෛනික දූව.", "නබි ﷺ බොහෝ විට කරන ලද දුවා."),
    )
}
